;place-items:center;flex:0 0 auto;border-radius:9px;background:#e4f5fb;color:#1480bd;font-weight:800;font-size:.78rem}.section-head h2{font-size:1.02rem}.section-head p{margin:4px 0 0;color:var(--muted);font-size:.84rem}.size-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:11px}.size{position:relative;padding:16px 13px;border:1px solid var(--line);border-radius:14px;cursor:pointer;transition:.2s}.size:hover,.size.selected{border-color:#43bfe0;background:#f1fbfe;box-shadow:0 7px 16px rgba(20,127,199,.08)}.size input{position:absolute;opacity:0}.size i{display:block;margin-bottom:10px;color:#1682bd;font-size:1.2rem}.size strong{display:block;font-size:.84rem}.size span{display:block;margin-top:3px;color:var(--muted);font-size:.72rem}.row{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px 0}.row+.row{border-top:1px solid #edf3f6}.row strong{display:block;font-size:.87rem}.row small{display:block;margin-top:3px;color:var(--muted);font-size:.75rem}.quantity{display:flex;align-items:center;border:1px solid var(--line);border-radius:10px;overflow:hidden}.quantity button{width:34px;height:34px;border:0;background:#fff;color:#177fbd;cursor:pointer;font-size:1rem}.quantity output{width:34px;text-align:center;font-size:.85rem;font-weight:800}.fulfillment{display:grid;grid-template-columns:1fr 1fr;gap:11px}.fulfillment label{display:flex;align-items:center;gap:11px;padding:14px;border:1px solid var(--line);border-radius:13px;cursor:pointer}.fulfillment label.selected{border-color:#42bee0;background:#f2fbfe}.fulfillment input{accent-color:#1682bd}.fulfillment strong{display:block;font-size:.84rem}.fulfillment span{display:block;margin-top:3px;color:var(--muted);font-size:.72rem}.review{position:sticky;top:18px;padding:22px;border-radius:20px;color:#eaf8ff;background:linear-gradient(150deg,#0b3a5a,#07597b);box-shadow:0 20px 42px rgba(3,43,66,.22)}.review h2{font-size:1.1rem;color:#fff}.review-intro{margin:7px 0 18px;color:#b9d9e8;font-size:.8rem}.review-list{padding:0;margin:0;list-style:none}.review-list li{display:flex;justify-content:space-between;gap:12px;padding:11px 0;border-top:1px solid rgba(217,246,255,.14);font-size:.82rem}.review-list span{color:#bdd9e7}.review-list strong{color:#fff;text-align:right}.note{display:flex;gap:8px;margin:16px 0;color:#c1dce8;font-size:.72rem;line-height:1.5}.note i{color:#65e3f2;margin-top:2px}.continue{display:flex;justify-content:center;align-items:center;gap:9px;width:100%;padding:13px;border-radius:11px;color:#06334c;background:#e9fbff;text-decoration:none;font-size:.86rem;font-weight:800}.login{display:block;margin-top:12px;color:#c7e1ec;text-align:center;text-decoration:none;font-size:.76rem;font-weight:700}@media(max-width:800px){.intro{display:block}.intro p{margin-top:13px}.layout{grid-template-columns:1fr}.review{position:static}.size-grid{grid-template-columns:1fr}.page{padding-top:32px}}@media(max-width:480px){.topbar-inner,.page{padding-left:17px;padding-right:17px}.setup{padding:19px}.fulfillment{grid-template-columns:1fr}.progress b{width:14px}}
